<?php if($error): ?><div class="alert alert-danger" role="alert"><?=e($error)?></div><?php endif; ?>
<?php if($result!==null): $deliveryCounts=array_count_values(array_column($result,'delivery_status')); ?><section class="card p-3 mb-3"><h2 class="h6">Import / invitation summary</h2><p><?=count($result)?> account invitation(s) processed. Email sent: <?=(int)($deliveryCounts['sent']??0)?>. Sending failed: <?=(int)($deliveryCounts['failed']??0)?>. Status unavailable: <?=(int)($deliveryCounts['pending']??0)?>. Email acceptance does not confirm receipt. Failed delivery leaves the account pending; use resend after checking SMTP.</p><ul><?php foreach($result as $row): ?><li>Account #<?=(int)$row['user_id']?> — <?=e(['sent'=>'Email sent','failed'=>'Sending failed','pending'=>'Sending status unavailable'][$row['delivery_status']]??'Sending status unavailable')?></li><?php endforeach; ?></ul></section><?php endif; ?>
<?php if($preview): $previewCounts=array_count_values(array_column($preview,'status')); ?><section class="card p-3 mb-3"><h2 class="h6">Review before creating accounts</h2><p role="status">Ready: <?=(int)($previewCounts['ready']??0)?>. Invalid: <?=(int)($previewCounts['invalid']??0)?>. Duplicates: <?=(int)($previewCounts['duplicate']??0)?>. No accounts have been created yet.</p><div class="table-responsive"><table class="table"><thead><tr><th>File row</th><th>Identity</th><th>Role / institutional ID</th><th>Email</th><th>Status</th><th>Validation</th></tr></thead><tbody><?php foreach($preview as $row):$p=$row['account']; ?><tr><td><?=$row['row']?></td><td><?=e($p['first_name'].' '.$p['last_name'].' / '.$p['username'])?></td><td><?=e($p['role'].' / '.$p['institutional_id'])?></td><td><?=e($p['email'])?></td><td><?=e(ucfirst($row['status']))?></td><td><?=e($row['errors']?implode(' ',$row['errors']):'Ready')?></td></tr><?php endforeach; ?></tbody></table></div><?php if(isset($_SESSION['account_provision_preview'])): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="create"><input type="hidden" name="nonce" value="<?=e($_SESSION['account_provision_preview']['nonce'])?>"><button class="btn btn-success">Create reviewed accounts and email activation links</button></form><?php else: ?><p class="text-danger">Correct the errors and preview again. No accounts were created.</p><?php endif; ?></section><?php endif; ?>
<section class="card p-3 mb-3"><h2 class="h6">Single account</h2><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="preview_single"><div class="col-12 col-md-4"><label class="form-label" for="provision-role">Role</label><select class="form-select" name="role" id="provision-role"><?php foreach(['student','teacher'] as $role): ?><option value="<?=$role?>"><?=ucfirst($role)?></option><?php endforeach; ?></select></div>
<?php foreach(['first_name'=>'First name','last_name'=>'Last name','username'=>'Username','institutional_id'=>'Official institutional ID','email'=>'Official email'] as $key=>$label): ?><div class="col-12 col-md-4"><label class="form-label" for="provision-<?=$key?>"><?=$label?></label><input class="form-control" id="provision-<?=$key?>" name="<?=$key?>" type="<?=$key==='email'?'email':'text'?>" maxlength="<?=$key==='email'?120:($key==='username'?50:($key==='institutional_id'?30:80))?>" required <?=$key==='email'?'aria-describedby="provision-email-state"':''?>><?php if($key==='email'): ?><small id="provision-email-state" role="status" aria-live="polite"></small><?php endif; ?></div><?php endforeach; ?><div class="col-12"><button class="btn btn-outline-success">Validate and preview account</button></div></form></section>
<section class="card p-3 mb-3"><h2 class="h6">Bulk import from CSV / Excel</h2><p>Download a template and fill it in Excel. Upload a single-sheet .xlsx workbook or UTF-8 CSV with plain values. Up to 100 accounts and 1 MB per batch. All rows must pass validation; existing accounts are never overwritten.</p><div class="d-flex gap-3 mb-3"><a href="?download=template">CSV template</a><a href="?download=template&amp;format=xlsx">Excel template</a></div><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="preview_csv"><label class="form-label" for="accounts-csv">CSV or Excel file</label><input class="form-control mb-3" id="accounts-csv" type="file" name="accounts_csv" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required><button class="btn btn-outline-success">Validate and preview import</button></form></section>
<section class="card p-3"><h2 class="h6">Resend activation</h2><p>Resending invalidates all previous links. Pending accounts only; wait one minute between successful sends.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="resend"><label class="form-label" for="resend-account">Account ID from People Directory</label><input class="form-control mb-3" id="resend-account" type="number" name="user_id" min="1" required><button class="btn btn-outline-success">Resend secure activation email</button></form></section>
</main></div></div><?php include __DIR__.'/../../components/footer.php'; ?><script src="<?=e(asset_url('js/account-provisioning.js',true))?>"></script></body></html>
